<?php
namespace Modules\BankingCoreDeposits\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\BankingCoreDeposits\Entities\DepositAccount; use Modules\BankingCoreDeposits\Entities\DepositTransaction; use Modules\BankingCoreDeposits\Services\DepositTransactionService;
class TransactionController extends Controller { public function index(){ $transactions=DepositTransaction::latest()->paginate(30); return view('bankingcoredeposits::transactions.index',compact('transactions')); } public function create(){ $accounts=DepositAccount::whereIn('status',['active','frozen'])->get(); return view('bankingcoredeposits::transactions.create',compact('accounts')); } public function store(Request $request, DepositTransactionService $service){ $account=DepositAccount::findOrFail($request->account_id); $service->post($account,$request->all()); return redirect()->route('banking.core-deposits.transactions.index')->with('status','Transaction posted'); } public function show(DepositTransaction $transaction){ return view('bankingcoredeposits::transactions.show',compact('transaction')); } }
